/usr/bin/bash -lc "paste <(gzip -cd /tmp/retained_1.fastqsanger.gz | awk 'NR%4==1{print "'$0}'"') <(gzip -cd /tmp/retained_2.fastqsanger.gz | awk 'NR%4==1{print "'$0}'"') | awk '
NF<4 {bad++; if(bad<=3) print \"missing mate at pair\",NR; next}
{
  f="'$1; r=$3
  sub(/''^@/,"",f); sub(/''^@/,"",r); sub(/'"\\/1"'$/,"",f); sub(/'"\\/2"'$/,"",r)
  if(f!=r){bad++; if(bad<=3) print "ID mismatch at pair",NR,$1,$3}
  if($2 !~ /'"\\/1"'$/ || $4 !~ /'"\\/2"'$/){labels++; if(labels<=3) print "mate label mismatch at pair",NR,$2,$4}
}
END{printf "retained_pair_sync: pairs=%d id_or_missing_errors=%d mate_label_errors=%d'"\\n\",NR,bad+0,labels+0; exit(bad||labels)}'
for retained_file in /tmp/retained_1.fastqsanger.gz /tmp/retained_2.fastqsanger.gz; do gzip -cd \""'$retained_file" | awk -v label="$retained_file" '"'
NR%4==1 && substr("'$0,1,1)!="@" {bad_header++}
NR%4==2 {sequence=$0}
NR%4==3 && substr($0,1,1)!="+" {bad_plus++}
NR%4==0 && length($0)!=length(sequence) {bad_length++}
END {printf "%s structure: records=%d lines_mod4=%d bad_headers=%d bad_plus=%d seq_qual_length_errors=%d'"\\n\",label,NR/4,NR%4,bad_header+0,bad_plus+0,bad_length+0; exit((NR%4)||bad_header||bad_plus||bad_length)}'; done"

/usr/bin/bash -lc "awk -v label='forward' '
FILENAME==ARGV[1] {
  h="'$0; if ((getline s)<=0 || (getline p)<=0 || (getline q)<=0) {truncated_orig++; next}
  split(h,a," "); key=a[1]; rec=h ORS s ORS p ORS q
  if (key in original) dup_orig++
  original[key]=rec; position[key]=++orig_n
  next
}
{
  h=$0; if ((getline s)<=0 || (getline p)<=0 || (getline q)<=0) {truncated_ret++; next}
  split(h,a," "); key=a[1]; rec=h ORS s ORS p ORS q
  if (key in seen_ret) dup_ret++
  seen_ret[key]=1; ret_n++
  if (!(key in original)) missing++
  else {
    if (original[key] != rec) modified++
    if (position[key] <= last_position) out_of_order++
    last_position=position[key]
  }
}
END {
  printf "%s: original=%d retained=%d missing=%d modified=%d out_of_order=%d duplicate_original_ids=%d duplicate_retained_ids=%d truncated=%d'"\\n\", label,orig_n,ret_n,missing,modified,out_of_order,dup_orig,dup_ret,truncated_orig+truncated_ret
  exit(missing||modified||out_of_order||dup_orig||dup_ret||truncated_orig||truncated_ret)
}' <(gzip -cd 'data/inputs/short_reads/pair/forward/forward.fastqsanger.gz') <(gzip -cd '/tmp/retained_1.fastqsanger.gz')"

